def maxSumAfterPartition(arr, k):
    n = len(arr)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        m = 0
        best = 0
        for L in range(1, min(k, i) + 1):
            if arr[i - L] > m:
                m = arr[i - L]
            v = dp[i - L] + m * L
            if v > best:
                best = v
        dp[i] = best
    return dp[n]
